// Markdown views of the registers in .tomdlc/state.json. state.json is the
// source of truth; these files are regenerated by sync-registers.ts after every
// state.json write, so people (and agents) can read the registers without
// parsing JSON, and the two can't drift.
//  - Fully generated (hook-only, nobody writes them with tools): risks.md,
//    findings.md, waivers.md, spikes.md, promotions.md, decisions.md.
//  - practices.md is the planner's prose; only its rule sections (Mandated,
//    Forbidden, Stage plan presets, Learned rules) are generated, between markers.
// A view is written only once its register exists in state.json, so a project
// whose decisions.md or practices.md predates the register keeps its file until
// the orchestrator migrates the entries.
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { DECISIONS_FILE } from "./hook.ts"

type Obj = Record<string, any>

export const PRACTICES_FILE = ".tomdlc/practices.md"
export const PRACTICE_KINDS = ["mandated", "forbidden", "preset", "learned"] as const

const NOTICE = (register: string) =>
  `<!-- Generated by a TomDLC hook from \`${register}\` in .tomdlc/state.json. Do not edit: changes here are overwritten. Ask the orchestrator to change the register. -->`
export const BLOCK_START = `<!-- tomdlc:generated practices: written by a TomDLC hook from \`practices\` in .tomdlc/state.json. Edits between these markers are replaced; ask the orchestrator to change the register. -->`
export const BLOCK_END = "<!-- /tomdlc:generated practices -->"
const BLOCK = /<!-- tomdlc:generated practices[\s\S]*?<!-- \/tomdlc:generated practices -->\n?/

const list = (v: unknown): Obj[] => (Array.isArray(v) ? v.filter((x) => x && typeof x === "object") : [])
const num = (id: unknown) => Number(String(id ?? "").match(/\d+$/)?.[0] ?? Infinity)
const byNum = (a: Obj, b: Obj) => num(a.id) - num(b.id)
const cell = (v: unknown) => (v == null ? "" : String(v).replaceAll("|", "\\|").replace(/\r?\n/g, "<br>"))
const day = (v: unknown) => String(v ?? "").slice(0, 10)

function table(headers: string[], rows: unknown[][]): string {
  if (rows.length === 0) return "None."
  return [`| ${headers.join(" | ")} |`, `|${headers.map(() => "---").join("|")}|`, ...rows.map((r) => `| ${r.map(cell).join(" | ")} |`)].join("\n")
}

const page = (register: string, title: string, ...sections: string[]) => [NOTICE(register), "", `# ${title}`, "", ...sections].join("\n").trimEnd() + "\n"

function risks(state: Obj): string {
  const all = list(state.risks).sort(byNum)
  const rows = (xs: Obj[]) =>
    table(
      ["ID", "Type", "Description", "Likelihood", "Impact", "Treatment", "Action", "Owner", "Review", "Decision"],
      xs.map((r) => [r.id, r.type, r.description, r.likelihood, r.impact, r.treatment, r.action, r.owner, r.review, r.decision]),
    )
  const open = all.filter((r) => r.status !== "closed")
  return page("risks", "Risk register",
    "Risks, assumptions, issues and dependencies (RAID). Security weaknesses are in `findings.md`, threats in `03-threat-model.md`.", "",
    `## Open (${open.length})`, "", rows(open), "",
    "## Closed", "", rows(all.filter((r) => r.status === "closed")))
}

const SEVERITY_ORDER = ["critical", "high", "medium", "low"]

function findings(state: Obj): string {
  const all = list(state.findings).sort(byNum)
  const open = all.filter((f) => f.status === "open").sort((a, b) => SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity) || byNum(a, b))
  const where = (f: Obj) => [f.stage, f.slice].filter(Boolean).join(" / ")
  return page("findings", "Findings register",
    `## Open (${open.length})`, "",
    table(["ID", "Severity", "Stage / slice", "Source", "Summary", "Pre-existing"], open.map((f) => [f.id, f.severity, where(f), f.source, f.summary, f.preexisting ? "yes" : ""])), "",
    "## Closed", "",
    table(["ID", "Severity", "Stage / slice", "Source", "Summary", "Status", "Decision or waiver"],
      all.filter((f) => f.status !== "open").map((f) => [f.id, f.severity, where(f), f.source, f.summary, f.status, f.waiver ?? f.decision])))
}

function waivers(state: Obj): string {
  return page("waivers", "Waivers",
    "Project-level and outlive changes. Scanner suppressions in code cite these IDs.", "",
    table(["ID", "Stages", "Criterion", "Reason", "Owner", "Expires", "Decision"],
      list(state.waivers).sort(byNum).map((w) => [w.id, [w.stage, ...(Array.isArray(w.stages) ? w.stages : [])].join(", "), w.criterion, w.reason, w.owner, w.expires, w.decision])))
}

function spikes(state: Obj): string {
  return page("spikes", "Spikes",
    table(["ID", "Question", "Status", "Outcome", "Decision"], list(state.spikes).sort(byNum).map((s) => [s.id, s.question, s.status, s.outcome, s.decision])))
}

function promotions(state: Obj): string {
  const env = state.environments ?? {}
  return page("environments.promotions", "Promotions",
    "## Promotions", "",
    table(["ID", "To", "Build", "Status", "Requested", "Approval", "Account before deploy", "Build running after"],
      list(env.promotions).sort(byNum).map((p) => [p.id, p.to, p.build, p.status, day(p.requestedAt), p.approval?.text ? `"${p.approval.text}" (${day(p.approval.at)})` : "", p.checks?.accountBeforeDeploy, p.checks?.deployedBuild])), "",
    "## Dev deploys", "",
    table(["Build", "Account", "At", "Smoke test"], list(env.devDeploys).map((d) => [d.build, d.account, day(d.at), d.smoke])))
}

function decisions(state: Obj): string {
  // Grouped under a dated heading naming the change and stage, in the order recorded.
  const groups: string[] = []
  let heading = ""
  for (const d of list(state.decisions).sort(byNum)) {
    const h = `## ${[day(d.date), d.change, d.stage].filter(Boolean).join(" · ")}`
    if (h !== heading) groups.push(`${groups.length ? "\n" : ""}${(heading = h)}\n`)
    const answer = d.default ? `Accepted default: ${d.answer}` : `Answer: ${d.answer}`
    groups.push(`- **${d.id}.** ${d.question}\n  ${answer}${d.confirmed ? " **(confirmed)**" : ""}`)
  }
  return page("decisions", "Decisions",
    "The user's answers, verbatim, and the defaults they accepted. Gate approvals and finding, risk and waiver decisions are in `state.json` and the other registers.", "",
    groups.length ? groups.join("\n") : "None yet.")
}

/** The generated rule sections of practices.md, markers included. */
export function practicesBlock(state: Obj): string {
  const rules = list(state.practices).sort(byNum)
  const of = (kind: string) => rules.filter((r) => r.kind === kind)
  const items = (xs: Obj[], line: (r: Obj) => string) => (xs.length ? xs.map(line).join("\n") : "None.")
  return [
    BLOCK_START,
    "## Mandated", "", items(of("mandated"), (r) => `- ${r.rule} (${r.id})`), "",
    "## Forbidden", "", items(of("forbidden"), (r) => `- ${r.rule} (${r.id})`), "",
    "## Stage plan presets", "", items(of("preset"), (r) => `- **${r.name}**${r.shape ? ` (shape: ${r.shape})` : ""}: ${r.rule} (${r.id})`), "",
    "## Learned rules", "", items(of("learned"), (r) => `- ${day(r.date)}: ${r.rule}${r.why ? ` (${r.why})` : ""} (${r.id})`),
    BLOCK_END,
  ].join("\n") + "\n"
}

const RULE_HEADINGS = /^## (Mandated|Forbidden|Stage plan presets|Learned rules)\s*$/

/**
 * practices.md with its rule sections replaced by the generated block. Without
 * markers (a file drafted before the register, or by hand), the rule sections are
 * removed wherever they are and the block is appended at the end.
 */
export function withPracticesBlock(original: string, state: Obj): string {
  // Work in LF and give the file back its own line endings (Windows checkouts are often CRLF).
  const text = original.replace(/\r\n/g, "\n")
  const eol = text === original ? "\n" : "\r\n"
  const block = practicesBlock(state)
  let out: string
  if (BLOCK.test(text)) {
    out = text.replace(BLOCK, block)
  } else {
    const kept: string[] = []
    let skipping = false
    for (const line of text.split("\n")) {
      if (/^#{1,2} /.test(line)) skipping = RULE_HEADINGS.test(line)
      if (!skipping) kept.push(line)
    }
    out = `${kept.join("\n").trimEnd()}\n\n${block}`
  }
  return out.replace(/\n/g, eol)
}

/** Rule entries written by hand in a practices.md that has no generated block yet. */
export function handWrittenRules(text: string): boolean {
  if (BLOCK.test(text)) return false
  let inRules = false
  // The template's hints are HTML comments and include an example rule line.
  for (const line of text.replace(/<!--[\s\S]*?-->/g, "").split(/\r?\n/)) {
    if (/^#{1,2} /.test(line)) inRules = RULE_HEADINGS.test(line)
    else if (inRules && /^\s*[-*]\s+\S/.test(line)) return true
  }
  return false
}

/** The fully generated views: path, the state.json key it comes from, and its renderer. */
export const VIEWS: { file: string; register: (s: Obj) => unknown; render: (s: Obj) => string }[] = [
  { file: ".tomdlc/risks.md", register: (s) => s.risks, render: risks },
  { file: ".tomdlc/findings.md", register: (s) => s.findings, render: findings },
  { file: ".tomdlc/waivers.md", register: (s) => s.waivers, render: waivers },
  { file: ".tomdlc/spikes.md", register: (s) => s.spikes, render: spikes },
  { file: ".tomdlc/promotions.md", register: (s) => s.environments?.promotions ?? s.environments?.devDeploys, render: promotions },
  { file: DECISIONS_FILE, register: (s) => s.decisions, render: decisions },
]

export const GENERATED_FILES = VIEWS.map((v) => v.file)

/** Writes `text` to `path` only when it differs, so unchanged registers cause no file churn. Returns whether it wrote. */
function writeIfChanged(path: string, text: string): boolean {
  if (existsSync(path) && readFileSync(path, "utf8") === text) return false
  writeFileSync(path, text)
  return true
}

/** Regenerates every view whose register exists, and practices.md's rule sections. Returns the files written. */
export function syncRegisters(root: string, state: Obj): string[] {
  const written: string[] = []
  for (const v of VIEWS) if (Array.isArray(v.register(state)) && writeIfChanged(join(root, v.file), v.render(state))) written.push(v.file)
  if (Array.isArray(state.practices) && syncPractices(root, state)) written.push(PRACTICES_FILE)
  return written
}

/** Rewrites practices.md's rule sections from the register, when the file and the register both exist. */
export function syncPractices(root: string, state: Obj): boolean {
  const path = join(root, PRACTICES_FILE)
  if (!Array.isArray(state.practices) || !existsSync(path)) return false
  return writeIfChanged(path, withPracticesBlock(readFileSync(path, "utf8"), state))
}
